package com.example.quanlybaotri.ticket.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="ticket_assignment_history") public class TicketAssignment{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="ticket_id")private MaintenanceTicket ticket;@Column(name="technician_id",nullable=false)private UUID technicianId;@Column(name="assigned_by_id",nullable=false)private UUID assignedById;@Column(name="assigned_at",nullable=false)private Instant assignedAt;@Column(name="unassigned_at")private Instant unassignedAt;@Column(length=500)private String reason;protected TicketAssignment(){}public TicketAssignment(MaintenanceTicket t,UUID tech,UUID by,String reason){ticket=t;technicianId=tech;assignedById=by;this.reason=reason;}@PrePersist void create(){if(id==null)id=UUID.randomUUID();if(assignedAt==null)assignedAt=Instant.now();}public void unassign(){if(unassignedAt==null)unassignedAt=Instant.now();}public UUID getTechnicianId(){return technicianId;}public UUID getAssignedById(){return assignedById;}}
